/* @lc app=leetcode id=3331 lang=kotlin */ class Solution { fun findSubtreeSizes(parent: IntArray, s: String): IntArray = parent.size.let { n -> parent.indices.drop(1).groupBy { parent[it] }.let { g -> IntArray(26) { -1 }.let { last -> IntArray(n).let { sv -> IntArray(n).let { np -> java.util.ArrayDeque<Int>().also { it.addFirst(0) }.let { st -> generateSequence { st.pollFirst() }.mapNotNull { e -> if (e >= 0) (s[e] - 'a').let { c -> np.set(e, if (last[c] >= 0) last[c] else parent[e]).also { sv[e] = last[c] }.also { last[c] = e }.also { st.addFirst(e.inv()) }.also { g[e].orEmpty().forEach { st.addFirst(it) } }.let { e } } else (s[e.inv()] - 'a').let { c -> last.set(c, sv[e.inv()]).let { null } } }.toList().reversed().let { order -> IntArray(n) { 1 }.also { sz -> order.forEach { v -> if (v != 0) sz[np[v]] += sz[v] } } } } } } } } } }